def skill():
    # 곱 = -3^(f/2) = -27 -> f(n) = 6 ; (n-3)^2 = k-6 , sqrt = 1, 2
    return sum(6 + d*d for d in (1, 2))

def count(k):
    return sum(1 for n in range(1, 200) if -(n-3)**2 + k == 6)

def standard():
    x = Symbol('x')
    ks = set()
    for n in range(1, 60):
        fn = 6  # product condition
        roots = [r for r in real_roots(x**4 - Integer(3)**fn)]
        assert simplify(roots[0]*roots[1] + 27) == 0
        ks.add(fn + (n-3)**2)
    return sum(k for k in ks if count(k) == 2)

def unique():
    good = []
    for k in range(-5, 150):
        c = 0
        for n in range(1, 40):
            f = -(n-3)**2 + k
            a = Integer(3)**f
            rs = [a**Rational(1, 4), -a**Rational(1, 4)]  # 양수의 네제곱근 중 실수
            if simplify(rs[0]*rs[1] + 27) == 0:
                c += 1
        if c == 2:
            good.append(k)
    return [sum(good)]
